INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "陆郢以苏州城应杨行密，成及被俘", "start_year": 896, "end_year": 896, "time_original": "896年五月癸未", "dynasty": "唐", "description": "苏州常熟镇使陆郢以州城响应杨行密，刺史成及被俘。", "phases": [], "location_name": "苏州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "6a58a640-ea25-5b1a-8ed6-89358c6243f1"}, {"title": "杨行密见成及所蓄图书药物，署行军司马", "start_year": 896, "end_year": 896, "time_original": "896年五月苏州陷后条；确日未另载", "dynasty": "唐", "description": "杨行密查看成及家中所蓄，只有图书和药物，认为他贤，带回并署为行军司马。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "a40e30bc-b0f8-584b-b2f2-d9afa4cf8452"}, {"title": "成及哭诉家属在钱镠处，欲自刺", "start_year": 896, "end_year": 896, "time_original": "896年五月受署后条；确日未另载", "dynasty": "唐", "description": "成及拜而哭泣，称家中百口在钱镠处，愿以自己一身换家属免死，随后拔佩刀欲自刺。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "a42f6081-f09c-5430-ae8f-b17677958831"}, {"title": "杨行密执成及手，止其自刺并馆于府舍", "start_year": 896, "end_year": 896, "time_original": "896年五月成及欲自刺时；确日未另载", "dynasty": "唐", "description": "杨行密立即握住成及的手，阻止其自刺，并安排他住在府舍。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "bee3d1eb-7c19-5a52-b266-fb01acf3da8e"}, {"title": "杨行密常单衣访成及并共饮食", "start_year": null, "end_year": null, "time_original": "卷260乾宁三年条所述往来背景；起讫未载", "dynasty": "唐", "description": "成及室内也有兵器，杨行密仍常穿单衣前往，与他一同饮食，书中记其无所疑。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "7380dfc8-b28c-54af-b82a-da70fe74ea16"}, {"title": "钱镠闻苏州陷，召顾全武趋西陵防杨行密", "start_year": 896, "end_year": 896, "time_original": "896年五月苏州陷后；确日未另载", "dynasty": "唐", "description": "钱镠听闻苏州陷落，急召顾全武，令其赴西陵防备杨行密。", "phases": [], "location_name": "西陵", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "6cbb769a-c781-584c-aa65-068ad304b262"}, {"title": "顾全武请先取越州后复苏州，钱镠从之", "start_year": 896, "end_year": 896, "time_original": "896年五月钱镠召还以后；确日未另载", "dynasty": "唐", "description": "顾全武认为越州是敌方根本，请先取越州再恢复苏州，钱镠听从。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "e838eff0-6405-552d-93a3-8c6c39d6d013"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

