ole": "下令召还者", "status": "draft", "id": "90e624d6-0c81-5f76-9b76-f146df776d35", "person_id": "d61d1f96-7af5-5367-8be8-7a25ee7c85ae", "event_id": "6cbb769a-c781-584c-aa65-068ad304b262"}, {"role": "被召将", "status": "draft", "id": "b38d57e1-168c-597d-ba4e-2ac115f999c9", "person_id": "82b73ae4-434c-5208-8a2d-89b0830434c2", "event_id": "6cbb769a-c781-584c-aa65-068ad304b262"}, {"role": "提出先越后苏者", "status": "draft", "id": "85f8c32e-228e-5e43-9f25-2e1cbccb006f", "person_id": "82b73ae4-434c-5208-8a2d-89b0830434c2", "event_id": "e838eff0-6405-552d-93a3-8c6c39d6d013"}, {"role": "采纳者", "status": "draft", "id": "afda4ae1-40f8-5b31-8d53-351035ce36a6", "person_id": "d61d1f96-7af5-5367-8be8-7a25ee7c85ae", "event_id": "e838eff0-6405-552d-93a3-8c6c39d6d013"}]'::jsonb)
