INSERT INTO public.fact_claim (id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status)
SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "苏州常熟镇使陆郢以州城响应杨行密，刺史成及被俘。", "citation": "卷260·乾宁三年（896）·zztj-v260-y0896-p017·原文件第98行", "note": "原文：癸未，苏州常熟镇使陆郢以州城应杨行密，虏刺史成及。；核对说明：州城指苏州，不将常熟镇误作州城；响应及俘获的具体执行者不另补。", "status": "draft", "id": "fc0d9d45-5f57-5f36-8c85-52a6180a4d6e", "subject_id": "6a58a640-ea25-5b1a-8ed6-89358c6243f1", "source_id": "98469cf2-27e5-5352-a615-5b7be1937da0"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "896年五月癸未", "citation": "卷260·乾宁三年（896）·zztj-v260-y0896-p017·原文件第98行", "note": "原文：癸未，苏州常熟镇使陆郢以州城应杨行密，虏刺史成及。；核对说明：州城指苏州，不将常熟镇误作州城；响应及俘获的具体执行者不另补。", "status": "draft", "id": "5d5427a0-7146-5137-9510-905a6c6eb617", "subject_id": "6a58a640-ea25-5b1a-8ed6-89358c6243f1", "source_id": "98469cf2-27e5-5352-a615-5b7be1937da0"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记陆郢：以城响应者。", "citation": "卷260·乾宁三年（896）·zztj-v260-y0896-p017·原文件第98行", "note": "原文：癸未，苏州常熟镇使陆郢以州城应杨行密，虏刺史成及。行密阅及家所蓄，惟图书、药物，贤之，归，署行军司马。及拜且泣曰：“及百口在钱公所。失苏州不能死，敢求富贵！愿以一身易百口之死！”引佩刀欲自刺。行密遽执其手，止之，馆于府舍。其室中亦有兵仗，行密每单衣诣之，与之共饮膳，无所疑。钱镠闻苏州陷，急召顾全武，使趋西陵备行密，全武曰：“越州贼之根本，奈何垂克而弃之！请先取越州，后复苏州。”镠从之。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "a9b25d1d-df31-5b18-bbb7-b50cd0ccadea", "subject_id": "30563822-2fe7-56c3-bcd7-a1e29f0b2190", "source_id": "98469cf2-27e5-5352-a615-5b7be1937da0"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "陆郢：以城响应者。", "citation": "卷260·乾宁三年（896）·zztj-v260-y0896-p017·原文件第98行", "note": "原文：癸未，苏州常熟镇使陆郢以州城应杨行密，虏刺史成及。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "f43ed4b5-80b5-5f17-b66e-b6b62841fe0a", "subject_id": "0279825b-7eaa-5a52-94e4-c449d6ca80cb", "source_id": "98469cf2-27e5-5352-a615-5b7be1937da0"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记杨行密：受响应者。", "citation":